pages.css:
.index-hero {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: var(--color-text-on-dark);
  padding: var(--spacing-2xl) 0;
  text-align: center;
}

.index-hero h1 {
  color: var(--color-text-on-dark);
  margin-bottom: var(--spacing-md);
}

.index-hero-subtitle {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: var(--spacing-md);
  color: var(--color-accent);
}

.index-hero p {
  font-size: 1.05rem;
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.index-cta-button {
  display: inline-block;
  background-color: var(--color-accent);
  color: #000;
  padding: var(--spacing-md) var(--spacing-lg);
  border-radius: 6px;
  font-weight: 700;
  font-size: 1.1rem;
  text-decoration: none;
  transition: all 0.2s ease;
  min-height: 44px;
  min-width: 44px;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.index-cta-button:hover {
  background-color: var(--color-accent-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.index-cta-button:focus {
  outline: 2px solid var(--color-text-on-dark);
  outline-offset: 2px;
}

.index-program {
  padding: var(--spacing-2xl) 0;
  background-color: var(--color-bg);
}

.index-program h2 {
  margin-bottom: var(--spacing-md);
}

.index-program > .container > p {
  margin-bottom: var(--spacing-xl);
  font-size: 1.05rem;
}

.index-program-card {
  display: flex;
  flex-direction: column;
}

.index-program-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.index-session-dates {
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.index-program-list {
  list-style: none;
  padding: 0;
  margin: var(--spacing-md) 0;
  flex-grow: 1;
}

.index-program-list li {
  padding: var(--spacing-xs) 0;
  padding-left: var(--spacing-md);
  position: relative;
}

.index-program-list li:before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--color-success);
  font-weight: 700;
}

.index-pricing {
  background-color: #f9f9f9;
  padding: var(--spacing-2xl) 0;
}

.index-pricing h2 {
  margin-bottom: var(--spacing-md);
}

.index-pricing > .container > p {
  margin-bottom: var(--spacing-xl);
  font-size: 1.05rem;
}

.index-price-card {
  display: flex;
  flex-direction: column;
}

.index-price-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.index-card-description {
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: var(--spacing-sm);
}

.index-price-weekly {
  font-size: 1.25rem;
  color: var(--color-success);
}

.index-price-list {
  list-style: none;
  padding: 0;
  margin: var(--spacing-md) 0;
  flex-grow: 1;
}

.index-price-list li {
  padding: var(--spacing-xs) 0;
  padding-left: var(--spacing-md);
  position: relative;
}

.index-price-list li:before {
  content: "•";
  position: absolute;
  left: 0;
  color: var(--color-primary-dark);
  font-weight: 700;
}

.index-price-note {
  font-size: 0.9rem;
  color: #666;
  margin-top: var(--spacing-md);
}

.index-pricing-extras {
  background-color: var(--color-bg);
  border: 2px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  margin-top: var(--spacing-xl);
}

.index-pricing-extras h3 {
  margin-bottom: var(--spacing-md);
  color: var(--color-primary-dark);
}

.index-extras-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.index-extras-list li {
  padding: var(--spacing-sm) 0;
  padding-left: var(--spacing-md);
  position: relative;
}

.index-extras-list li:before {
  content: "→";
  position: absolute;
  left: 0;
  color: var(--color-primary-dark);
  font-weight: 700;
}

.index-testimonials {
  padding: var(--spacing-2xl) 0;
  background-color: var(--color-bg);
}

.index-testimonials h2 {
  margin-bottom: var(--spacing-xl);
}

.index-registration {
  background-color: #f9f9f9;
  padding: var(--spacing-2xl) 0;
}

.index-registration h2 {
  margin-bottom: var(--spacing-md);
}

.index-registration > .container > p {
  margin-bottom: var(--spacing-xl);
  font-size: 1.05rem;
}

.index-form {
  background-color: var(--color-bg);
  padding: var(--spacing-xl);
  border-radius: 8px;
  box-shadow: var(--shadow-sm);
}

.index-fieldset {
  border: none;
  padding: 0;
  margin-bottom: var(--spacing-xl);
}

.index-fieldset:last-of-type {
  margin-bottom: var(--spacing-lg);
}

.index-legend {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
  padding-bottom: var(--spacing-sm);
  border-bottom: 2px solid var(--color-border);
}

.index-checkbox-group {
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-md);
}

.index-checkbox-group input[type="checkbox"] {
  width: auto;
  min-width: 20px;
  min-height: 20px;
  margin-top: 12px;
  flex-shrink: 0;
}

.index-checkbox-label {
  display: inline;
  font-weight: 400;
  margin-bottom: 0;
}

.index-submit-button {
  width: 100%;
  padding: var(--spacing-md);
  font-size: 1.1rem;
}

.index-form-note {
  margin-top: var(--spacing-md);
  font-size: 0.9rem;
  color: #666;
  text-align: center;
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-xl) 0;
  }

  .index-hero-subtitle {
    font-size: 1.1rem;
  }

  .index-hero p {
    font-size: 1rem;
  }

  .index-program,
  .index-pricing,
  .index-testimonials,
  .index-registration {
    padding: var(--spacing-xl) 0;
  }

  .index-form {
    padding: var(--spacing-lg);
  }

  .index-legend {
    font-size: 1.1rem;
  }

  .index-checkbox-group input[type="checkbox"] {
    margin-top: 8px;
  }
}

@media (min-width: 601px) {
  .index-form-group-inline {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-md);
  }
}

